import{_ as s,o as e,c as t,a5 as i}from"./chunks/framework.BTidRIrv.js";const r="/assets/pw.D0y6PZ9d.png",g=JSON.parse('{"title":"2. 安装和使用","description":"","frontmatter":{},"headers":[],"relativePath":"tr/use.md","filePath":"tr/use.md"}'),l={name:"tr/use.md"};function o(n,a,h,p,d,k){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="_2-安装和使用" tabindex="-1">2. 安装和使用 <a class="header-anchor" href="#_2-安装和使用" aria-label="Permalink to &quot;2. 安装和使用&quot;">​</a></h1><h2 id="_0-阅读并同意免责声明" tabindex="-1">0. 阅读并同意免责声明 <a class="header-anchor" href="#_0-阅读并同意免责声明" aria-label="Permalink to &quot;0. 阅读并同意免责声明&quot;">​</a></h2><p>作为用户，你首先需要明确：<strong>使用trapdoor带来的功能就意味着承担第三方软件带来的风险。<strong>为了不给开发者带来不必要的麻烦，请阅读如下的免责声明，如果</strong>你使用了trapdoor就意味着你自动同意了该声明</strong>。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>免责声明 trapdoor(以下简称tr)是一个利用dll远程注入技术开发的BDS辅助软（插）件，它提供了不少方便玩家的功能，给生电玩家创造了便利。此外，tr本身是开源免费的，内部没有任何恶意代码，原则上也不会对存档造成任何损害。</p><p>但是考虑到此类软件的特殊性，开发者无法完全保证tr对用户的存档不造成任何破坏，万一发生意外情况，开发者不会也没有能力对tr对用户 造成的损失负责。</p><p>如果你继续使用tr插件，那么就代表你同意了该声明(或者说叫用户协议)，如果你不想承担此类风险，请停止使用tr插件。</p><p>附录： 以下是一些使用建议:</p><ul><li>及时更新插件到新版本，因为目前tr还是beta版，理论上越更新bug肯会越少</li><li>尽量关闭不用的功能</li><li>及时备份存档永远是好习惯 2022.1.11</li></ul></div><h2 id="_1-下载bds" tabindex="-1">1. 下载BDS <a class="header-anchor" href="#_1-下载bds" aria-label="Permalink to &quot;1. 下载BDS&quot;">​</a></h2><p>插件是依托于BDS的，因此使用trapdoor之前需要下载BDS。前往<a href="https://www.minecraft.net/en-us/download/server/bedrock" target="_blank" rel="noreferrer">https://www.minecraft.net/en-us/download/server/bedrock</a>下载<strong>正确版本</strong>的Windows版的BDS文件，并解压到任意文件夹。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>文件夹路径中不建议包含中文字符。</strong></p></div><h2 id="_2-开启loop-back" tabindex="-1">2. 开启Loop back <a class="header-anchor" href="#_2-开启loop-back" aria-label="Permalink to &quot;2. 开启Loop back&quot;">​</a></h2><p>UWP应用默认关闭了loop back（默认情况下UWP应用无法连接localhost）,你需要开启才能连接本地服务器，<strong>如果是云服务器的多人游戏可以省去这一步</strong>。以管理员权限打开<code>powershell</code>,并运行如下命令(该命令来自微软官网):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CheckNetIsolation.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LoopbackExempt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1958404141</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86561845</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1752920682</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3514627264</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">368642714</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">62675701</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">733520436</span></span></code></pre></div><p>如果该步骤顺利的话<code>powershell</code>会输出&quot;完成&quot;二字，如下图所示：</p><p><img src="'+r+`" alt=""></p><h2 id="_3-安装liteloaderbds" tabindex="-1">3. 安装LiteLoaderBDS <a class="header-anchor" href="#_3-安装liteloaderbds" aria-label="Permalink to &quot;3. 安装LiteLoaderBDS&quot;">​</a></h2><p>参考<a href="https://github.com/LiteLDev/LiteLoaderBDS#for-windows" target="_blank" rel="noreferrer">LiteLoaderBDS中文安装教程</a>安装服务器对应版本的LiteLoaderBDS。<strong>如遇到LiteloaderBDS相关的问题请前往<a href="https://github.com/LiteLDev/LiteLoaderBDS/issues" target="_blank" rel="noreferrer">这里</a>这里进行反馈。而不是找本插件开发者</strong>。</p><h2 id="_4-下载并安装插件本体" tabindex="-1">4. 下载并安装插件本体 <a class="header-anchor" href="#_4-下载并安装插件本体" aria-label="Permalink to &quot;4. 下载并安装插件本体&quot;">​</a></h2><h4 id="方法1" tabindex="-1">方法1 <a class="header-anchor" href="#方法1" aria-label="Permalink to &quot;方法1&quot;">​</a></h4><ol><li>前往<a href="https://github.com/hhhxiao/trapdoor-ll/releases" target="_blank" rel="noreferrer">Trapdoor的下载页面</a>下载发布的release文件</li><li><strong>解压下载到的压缩包，把所有文件复制到BDS的根目录即可</strong>这时候相关配置文件的路径如下所示：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└───bedrock-server-xxx</span></span>
<span class="line"><span>  └───plugins</span></span>
<span class="line"><span>  	└───trapdoor-xx-xx.dll</span></span>
<span class="line"><span>    └───trapdoor</span></span>
<span class="line"><span>         └───config.json</span></span></code></pre></div><h4 id="方法2" tabindex="-1">方法2 <a class="header-anchor" href="#方法2" aria-label="Permalink to &quot;方法2&quot;">​</a></h4><p>在较新的版本中release内会内置<code>installer.exe</code>你可以在解压后直接双击该可执行程序，选中BDS根目录并点击安装即可。</p><h2 id="_5-配置配置文件" tabindex="-1">5. 配置配置文件 <a class="header-anchor" href="#_5-配置配置文件" aria-label="Permalink to &quot;5. 配置配置文件&quot;">​</a></h2><p>创造服一般可用不配置，生存服可能需要根据需求关闭部分功能(如<code>tick</code>，漏斗计数器等)。具体配置参考<a href="/tr/config.html">配置文件</a>一节。</p><h2 id="_6-加载材质包" tabindex="-1">6. 加载材质包 <a class="header-anchor" href="#_6-加载材质包" aria-label="Permalink to &quot;6. 加载材质包&quot;">​</a></h2><p>下载纹理包，然后客户端加载该纹理包即可(<strong>不是服务端，是每个玩家都要在本地加载，和普通材质包一样使用</strong>)，加载好的游戏截图如下所示：</p><p>由于本插件的资源包系统修改过多次，因此不同的版本会有不同的资源表需求，具体见下表：</p><table tabindex="0"><thead><tr><th>版本</th><th>资源包下载</th></tr></thead><tbody><tr><td>beta ~ 0.18</td><td><a href="https://github.com/OEOTYAN/Trapdoor-CUI/releases/tag/v0.4" target="_blank" rel="noreferrer">Trapdoor CUI v0.4</a></td></tr><tr><td>0.19 ~ 0.25</td><td><a href="https://github.com/OEOTYAN/Trapdoor-CUI/releases/tag/v5.0" target="_blank" rel="noreferrer">Trapdoor CUI v5.0</a> + <a href="https://github.com/OEOTYAN/LiteLoaderBDS-CUI/releases/tag/ll.1.0" target="_blank" rel="noreferrer">LiteLoaderBDS CUI 1.0</a></td></tr><tr><td>0.26 +</td><td><a href="https://github.com/OEOTYAN/LiteLoaderBDS-CUI/releases/tag/v1.1" target="_blank" rel="noreferrer">LiteLoaderBDS CUI 1.1</a></td></tr></tbody></table><h2 id="_7-连接服务器进入游戏" tabindex="-1">7. 连接服务器进入游戏 <a class="header-anchor" href="#_7-连接服务器进入游戏" aria-label="Permalink to &quot;7. 连接服务器进入游戏&quot;">​</a></h2><p>如果你是本地开服,IP填写<code>127.0.0.1</code>或者<code>localhost</code>，如果你用的是云服务器而不是本地，填公网IP即可(不知道的问你们服务器的服主)。端口按照自己的设置在服务器的配置文件里面改，默认<code>19132</code>。</p>`,28)])])}const b=s(l,[["render",o]]);export{g as __pageData,b as default};
